//#region ../shared/utils/collider.ts
var collider = {
	Type: {
		Circle: 0,
		Aabb: 1
	},
	createCircle(pos, rad) {
		return {
			type: collider.Type.Circle,
			pos: v2.copy(pos),
			rad
		};
	},
	createAabb(min, max) {
		return {
			type: collider.Type.Aabb,
			min: v2.copy(min),
			max: v2.copy(max)
		};
	},
	createAabbExtents(pos, extent) {
		const min = v2.sub(pos, extent);
		const max = v2.add(pos, extent);
		return collider.createAabb(min, max);
	},
	createBounding(colliders) {
		if (colliders.length === 1) return collider.copy(collider.toAabb(colliders[0]));
		const aabbs = [];
		for (let i = 0; i < colliders.length; i++) {
			const col = colliders[i];
			aabbs.push(collider.toAabb(col));
		}
		const bound = coldet.boundingAabb(aabbs);
		return collider.createAabb(bound.min, bound.max);
	},
	toAabb(c) {
		if (c.type === collider.Type.Aabb) return collider.createAabb(c.min, c.max);
		const aabb = coldet.circleToAabb(c.pos, c.rad);
		return collider.createAabb(aabb.min, aabb.max);
	},
	copy(c) {
		return c.type === collider.Type.Circle ? collider.createCircle(c.pos, c.rad) : collider.createAabb(c.min, c.max);
	},
	transform(col, pos, rot, scale) {
		if (col.type === collider.Type.Aabb) {
			const e = v2.mul(v2.sub(col.max, col.min), .5);
			const c = v2.add(col.min, e);
			const pts = [
				v2.create(c.x - e.x, c.y - e.y),
				v2.create(c.x - e.x, c.y + e.y),
				v2.create(c.x + e.x, c.y - e.y),
				v2.create(c.x + e.x, c.y + e.y)
			];
			const min = v2.create(Number.MAX_VALUE, Number.MAX_VALUE);
			const max = v2.create(-Number.MAX_VALUE, -Number.MAX_VALUE);
			for (let i = 0; i < pts.length; i++) {
				const p = v2.add(v2.rotate(v2.mul(pts[i], scale), rot), pos);
				min.x = math.min(min.x, p.x);
				min.y = math.min(min.y, p.y);
				max.x = math.max(max.x, p.x);
				max.y = math.max(max.y, p.y);
			}
			return collider.createAabb(min, max);
		}
		return collider.createCircle(v2.add(v2.rotate(v2.mul(col.pos, scale), rot), pos), col.rad * scale);
	},
	getPoints(aabb) {
		const pts = [];
		const { min } = aabb;
		const { max } = aabb;
		pts[0] = v2.create(min.x, min.y);
		pts[1] = v2.create(min.x, max.y);
		pts[2] = v2.create(max.x, min.y);
		pts[3] = v2.create(max.x, max.y);
		return pts;
	},
	intersectCircle(col, pos, rad) {
		if (col.type === collider.Type.Aabb) return coldet.intersectAabbCircle(col.min, col.max, pos, rad);
		return coldet.intersectCircleCircle(col.pos, col.rad, pos, rad);
	},
	intersectAabb(col, min, max) {
		if (col.type === collider.Type.Aabb) return coldet.intersectAabbAabb(col.min, col.max, min, max);
		return coldet.intersectAabbCircle(min, max, col.pos, col.rad);
	},
	intersectSegment(col, a, b) {
		if (col.type === collider.Type.Aabb) return coldet.intersectSegmentAabb(a, b, col.min, col.max);
		return coldet.intersectSegmentCircle(a, b, col.pos, col.rad);
	},
	intersect(colA, colB) {
		if (colB.type === collider.Type.Aabb) return collider.intersectAabb(colA, colB.min, colB.max);
		return collider.intersectCircle(colA, colB.pos, colB.rad);
	}
};

