function createCrate(overrides) {
	const baseDef = {
		type: "obstacle",
		category: "crate",
		scale: {
			createMin: 1,
			createMax: 1,
			destroy: .5
		},
		collision: collider.createAabbExtents(v2.create(0, 0), v2.create(2.25, 2.25)),
		height: .5,
		collidable: true,
		destructible: true,
		health: 75,
		hitParticle: "woodChip",
		explodeParticle: "woodPlank",
		reflectBullets: false,
		loot: [tierLoot("tier_world", 1, 1)],
		map: {
			display: true,
			color: 6697728,
			scale: .875
		},
		terrain: {
			grass: true,
			beach: true,
			riverShore: true
		},
		img: {
			sprite: "map-crate-01.img",
			residue: "map-crate-res-01.img",
			scale: .5,
			alpha: 1,
			tint: 16777215,
			zIdx: 10
		},
		sound: {
			bullet: "wood_crate_bullet",
			punch: "wood_crate_bullet",
			explode: "crate_break_02",
			enter: "none"
		}
	};
	return util.mergeDeep(baseDef, overrides);
}
